      </header>

      <div className="max-w-7xl mx-auto px-6 py-10 w-full flex flex-col lg:flex-row gap-10">
        <aside className="lg:w-56 space-y-10 flex-shrink-0">
          <div>
            <div className="flex items-center gap-2 mb-6 px-1">
              <Clock className="w-4 h-4 text-gray-400" />
              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">时间轴归档</h3>
            </div>
            <div className="space-y-1">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-4 py-3 rounded-xl text-sm font-bold transition-all flex items-center justify-between group ${
                  selectedMonth === null ? 'bg-white border border-gray-100 shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
                }`}
              >
                <span className="flex items-center gap-2">
                  <Hash className={`w-3.5 h-3.5 ${selectedMonth === null ? 'text-red-500' : 'text-gray-300 group-hover:text-gray-400'}`} />
                  全部时间
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded-full ${selectedMonth === null ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                  {insights.length}
                </span>
              </button>

              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-sm font-bold transition-all flex items-center justify-between group ${
                    selectedMonth === month ? 'bg-white border border-gray-100 shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  <span className="flex items-center gap-2">
                    <Calendar className={`w-3.5 h-3.5 ${selectedMonth === month ? 'text-red-500' : 'text-gray-300 group-hover:text-gray-400'}`} />
                    {month}
                  </span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-full ${selectedMonth === month ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                    {count}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 mb-12">
            <div>
              <h2 className="text-3xl font-bold text-gray-900 tracking-tight italic">
                每一天都有新的洞察。
              </h2>
            </div>

            <div className="flex items-center gap-4">
              <div className="flex bg-gray-100/80 p-1 rounded-xl items-center">
                <button 
                  onClick={() => setSortMode('timeline')}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[10px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  <CalendarDays className="w-3 h-3" />
                  时间线
                </button>
                <button 
                  onClick={() => setSortMode('category')}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[10px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  <ListFilter className="w-3 h-3" />
                  按类别
                </button>
              </div>

              <div className="text-sm text-gray-400 font-medium bg-white px-4 py-1.5 rounded-full border border-gray-100 shadow-sm">
                共计 <span className="text-gray-900 font-bold">{filteredInsights.length}</span> 条见解
              </div>
            </div>
          </div>

          {/* 活跃见解区域 */}
          {activeItems.length > 0 ? (
            <div className="space-y-16">
              <div className="flex items-center gap-3 mb-2">
                <Inbox className="w-5 h-5 text-gray-900" />
                <h3 className="text-lg font-black text-gray-900">活跃洞察</h3>
              </div>
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel} className="relative">
                  <div className="flex items-center gap-4 mb-8 sticky top-[152px] z-10 py-2 bg-[#fafafa]/80 backdrop-blur-sm">
                    <div className="h-px flex-grow bg-gray-100"></div>
                    <div className="flex items-center gap-2 px-6 py-2 bg-white rounded-full border border-gray-100 shadow-sm">
                      {sortMode === 'timeline' ? <Calendar className="w-3.5 h-3.5 text-red-500" /> : <Hash className="w-3.5 h-3.5 text-blue-500" />}
                      <span className="text-xs font-black text-gray-900 tracking-tight">{groupLabel}</span>
                    </div>
                    <div className="h-px flex-grow bg-gray-100"></div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                        onDelete={handleDeleteInsight}
                        onToggleStatus={handleToggleStatus}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : filteredInsights.length === 0 && (
            <div className="text-center py-40 bg-white rounded-[3rem] border border-gray-100 shadow-sm">
              <div className="max-w-xs mx-auto">
                <div className="w-16 h-16 bg-gray-50 rounded-3xl flex items-center justify-center mx-auto mb-6">
                  <Clock className="w-8 h-8 text-gray-200" />
                </div>
                <h3 className="text-lg font-bold text-gray-900 mb-2">暂无匹配记录</h3>
                <p className="text-sm text-gray-400 mb-8 leading-relaxed">
                  在该筛选条件下未找到任何分析。尝试更换分类或查看其他月份。
                </p>
                <button 
                  onClick={() => { setActiveCategory('全部'); setSelectedMonth(null); }}
                  className="inline-flex items-center gap-2 px-8 py-3 bg-gray-900 rounded-2xl font-bold text-sm text-white hover:bg-black transition-all shadow-xl shadow-gray-200"
                >
                  重置筛选条件
                </button>
              </div>
            </div>
          )}

          {/* 已归档见解区域 */}
          {archivedItems.length > 0 && (
            <div className="mt-24 space-y-8">
              <div className="flex items-center justify-between border-t border-dashed border-gray-200 pt-16">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-gray-100 rounded-xl">
                    <Archive className="w-5 h-5 text-gray-400" />
                  </div>
                  <div>
                    <h3 className="text-lg font-black text-gray-400">已归档历史</h3>
                    <p className="text-[10px] font-bold text-gray-300 uppercase tracking-widest">已失效的市场分析将自动移动至此</p>
                  </div>
                </div>
                <span className="text-[10px] font-black text-gray-300 bg-gray-50 px-3 py-1 rounded-full border border-gray-100">
                  {archivedItems.length} 条归档
                </span>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 grayscale-[0.5]">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                    onDelete={handleDeleteInsight}
                    onToggleStatus={handleToggleStatus}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      <footer className="mt-auto border-t border-gray-100 py-10 bg-white">
        <div className="max-w-7xl mx-auto px-6 text-center">
          <p className="text-[10px] text-gray-300 font-bold uppercase tracking-[0.3em]">个人交易日记 system · 洞察记录与回溯</p>
        </div>
      </footer>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;
